  Ltac tlw_sc w x0 i E21 E23 E33 RD0 WSH :=
    first
      [ eapply (sc_disj_lit asegs _ _ _ _ _ _ (wa_words w + 4 * i) 4 (wa_ff w / 8 + (SHBASE + 56)) 1);
          [ rewrite (estart_var _ 23 0 _ E23); lia | apply elit_u; lia
          | unfold estart, FSHB, WV_FF; cbn [a_base a_off]; rewrite (srl3_val _ (EVar 33) (wa_ff w) E33 ltac:(lia)); reflexivity
          | apply elit_u; lia | lia | lia | lia | unfold SHBASE; Z.div_mod_to_equations; lia | lia
          | unfold SHBASE; Z.div_mod_to_equations; lia | unfold SHBASE in *; Z.div_mod_to_equations; lia ]
      | eapply (sc_rd_w4s _ _ _ (wa_words w + 4 * i) _ _);
          [ apply (adenot_of_estart _ _ (wa_words w + 4 * i)); [rewrite (estart_var _ 23 0 _ E23); lia | lia] | exact RD0 | ev_xs; reflexivity ]
      | eapply (sc_flat_lit asegs _ _ _ _ (wa_words w + 4 * i) 4); [rewrite (estart_var _ 23 0 _ E23); lia | apply elit_u; lia | lia | lia | lia]
      | eapply (sc_flat_lit asegs _ _ _ _ ((wa_words w + 4 * i) / 8 + SHBASE) 1);
          [apply (estart_sh _ (EVar 21) (wa_words w + 4 * i) E21); lia | apply elit_u; lia
          | unfold SHBASE; Z.div_mod_to_equations; lia | lia | unfold SHBASE; Z.div_mod_to_equations; lia]
      | match goal with |- ?g => idtac "SCLEFT" g end ].

  Ltac tlw_post w s LB LBs m mo cj F fc x0 en Q OK KR1 VIS1 RF1 X1 HTx1 HR1 Hlf1 XR0 G24 G3_0 G4_0 K Q3 Q7 Q9 Q6 Q13 E33 HFW :=
    let HT1 := fresh "HT1" in
    pose proof (regs_tbl_restrict w [] _ _ RT_FXE HTx1 ltac:(vm_compute; reflexivity)) as HT1;
    lazymatch type of X1 with PMXAT _ _ _ _ _ _ ?mA ?mo1 _ _ _ _ _ ?spX =>
    lazymatch type of VIS1 with _ = MS ?R1 _ _ _ _ _ _ =>
    lazymatch goal with |- as_SR _ _ (mkCfg ?msF1 _) =>
    eapply (pm_leafW H HHm3 LINV LINV_frame AT_FIXWORD 0 _ _ _ HFW (x0, en) [] w s LB LBs mA mo1 cj S_WORD TBL_EEF44 [] [] spX msF1 R1 F fc 0xf2454 Q []);
      [ exact OK | exact X1 | exact KR1 | exact VIS1 | exact RF1 | rtf HT1 | rtf HT1 | reflexivity | lia | lia | reflexivity | reflexivity
      | cbn beta iota; split; [exact XR0|]; split; [rewrite (HR1 10%bv); etransitivity; [| exact (swrap32_sx32A x0 XR0)]; ev_xs; reflexivity|];
        split; [lia|]; rewrite (HR1 11%bv); exact G24
      | vm_compute; reflexivity | apply incl_refl | reflexivity | reflexivity
      | intros r0 r1 m9 k9 n9 a9 _ Hin9; destruct Hin9
      | ];
    let KR2 := fresh "KR2" in let VIS2 := fresh "VIS2" in let RF2 := fresh "RF2" in let X2 := fresh "X2" in
    let KEEP2 := fresh "KEEP2" in let MU2 := fresh "MU2" in let WM2 := fresh "WM2" in
    intros ? ? ? ? KR2 VIS2 RF2 X2 KEEP2 MU2 WM2 (r & Hr & Er);
    eapply (K _ _ _ _ r KR2 VIS2 RF2 X2);
      [ exact (regs_tbl_sub w _ _ _ RT_LOOPC (regs_keep w [] _ _ RT_FXE HT1 KEEP2) ltac:(vm_compute; reflexivity))
      | rewrite (KEEP2 3%bv ltac:(inb)), (HR1 3%bv); exact G3_0
      | rewrite (KEEP2 4%bv ltac:(inb)), (HR1 4%bv); exact G4_0
      | rewrite (KEEP2 19%bv ltac:(inb)), (HR1 19%bv); reflexivity
      | rewrite (KEEP2 21%bv ltac:(inb)), (HR1 21%bv); reflexivity
      | rewrite (KEEP2 23%bv ltac:(inb)), (HR1 23%bv); reflexivity
      | rewrite (KEEP2 24%bv ltac:(inb)), (HR1 24%bv); reflexivity
      | rewrite (KEEP2 27%bv ltac:(inb)), (HR1 27%bv); reflexivity
      | exact Hr | exact Er
      |
        let MU := fresh "MU" in
        pose proof (munch_sym _ m _ [(FSHB, SHBASE + 56, SHBASE + 57)] Hlf1 ltac:(vm_compute; reflexivity)) as MU;
        cbn [num_wins map] in MU; unfold FSHB, WV_P, WV_FF in MU;
        rewrite (srl3_val _ (EVar 33) (wa_ff w) E33 ltac:(lia)) in MU;
        eapply (ffkeep_trans w);
        [ apply (ffkeep_munch w _ _ _ MU (wmono_mem_denot _ _ _));
          apply Forall_cons; [cbn [fst snd]; rewrite Q13 in Q6; unfold SHBASE in *; destruct Q6 as [Q6|Q6]; [left | right]; lia | apply Forall_nil]
        | apply (ffkeep_munch w _ _ _ MU2 WM2); apply Forall_cons; [cbn [fst snd]; lia | apply Forall_nil] ] ]
    end end end.

  Lemma tl_wA : forall (spal : Z) (w : pmwA H) s LB LBs m mo (cj : pmc) msF R F fc (i en : Z) (Q : config -> Prop),
    pmw_okA H w -> PMXAT H LINV w s LB LBs m mo cj S_OPER TBL_EEF44 [] [] spal ->
    as_AKREL H s (mkCfg msF mo) -> as_VIS H s msF = MS R F (Z_to_bv 64 0xf2430) fc None m (seg_rom asegs) -> rfull R ->
    regs_tbl w R RT_LOOPC -> PropExec.getr R 3%bv = wa_gp w -> PropExec.getr R 4%bv = wa_tp w ->
    PropExec.getr R 21%bv = Z_to_bv 64 (wa_words w + 4 * i) -> PropExec.getr R 23%bv = Z_to_bv 64 (wa_words w + 4 * i) ->
    PropExec.getr R 24%bv = Z_to_bv 64 en -> 0 <= en < 2 ^ 32 ->
    wa_words w <> 0 -> 0 <= i < wa_n w ->
    (forall msF1 mo1 m1 R1 (r : Z),
       as_AKREL H s (mkCfg msF1 mo1) -> as_VIS H s msF1 = MS R1 F (Z_to_bv 64 0xf2454) fc None m1 (seg_rom asegs) -> rfull R1 ->
       PMXAT H LINV w s LB LBs m1 mo1 cj S_WORD TBL_EEF44 [] [] spal ->
       regs_tbl w R1 RT_LOOPC -> PropExec.getr R1 3%bv = wa_gp w -> PropExec.getr R1 4%bv = wa_tp w ->
       PropExec.getr R1 19%bv = PropExec.getr R 19%bv -> PropExec.getr R1 21%bv = PropExec.getr R 21%bv ->
       PropExec.getr R1 23%bv = PropExec.getr R 23%bv -> PropExec.getr R1 24%bv = PropExec.getr R 24%bv ->
       PropExec.getr R1 27%bv = PropExec.getr R 27%bv ->
       0 <= r < 2 ^ 32 -> PropExec.getr R1 10%bv = Z_to_bv 64 (sx32A r) ->
       ffkeep w m m1 ->
       as_SR H Q (mkCfg msF1 mo1)) ->
