  Lemma tl_next : forall (spal : Z) (w : pmwA H) s LB LBs m mo (cj : pmc) msF R F fc (k src : Z) (Q : config -> Prop),
    pmw_okA H w -> PMXAT H LINV w s LB LBs m mo cj S_WORD TBL_EEF44 [] [] spal ->
    as_AKREL H s (mkCfg msF mo) -> as_VIS H s msF = MS R F (Z_to_bv 64 0xf2500) fc None m (seg_rom asegs) -> rfull R ->
    regs_tbl w R RT_LOOPC -> PropExec.getr R 3%bv = wa_gp w -> PropExec.getr R 4%bv = wa_tp w ->
    PropExec.getr R 19%bv = Z_to_bv 64 (4 * k) -> 1 <= k < 2 ^ 16 ->
    PropExec.getr R 21%bv = Z_to_bv 64 src -> PropExec.getr R 23%bv = Z_to_bv 64 src -> 0 <= src -> src + 4 <= 2 ^ 47 ->
    (1 < k -> forall msF1 mo1 m1 R1,
       as_AKREL H s (mkCfg msF1 mo1) -> as_VIS H s msF1 = MS R1 F (Z_to_bv 64 0xf2430) fc None m1 (seg_rom asegs) -> rfull R1 ->
       PMXAT H LINV w s LB LBs m1 mo1 cj S_OPER TBL_EEF44 [] [] spal ->
       regs_tbl w R1 RT_LOOPC -> PropExec.getr R1 3%bv = wa_gp w -> PropExec.getr R1 4%bv = wa_tp w ->
       PropExec.getr R1 19%bv = Z_to_bv 64 (4 * (k - 1)) ->
       PropExec.getr R1 21%bv = Z_to_bv 64 (src + 4) -> PropExec.getr R1 23%bv = Z_to_bv 64 (src + 4) ->
       PropExec.getr R1 24%bv = PropExec.getr R 24%bv -> PropExec.getr R1 27%bv = PropExec.getr R 27%bv ->
       ffkeep w m m1 ->
       as_SR H Q (mkCfg msF1 mo1)) ->
    (k = 1 -> forall msF1 mo1 m1 R1,
       as_AKREL H s (mkCfg msF1 mo1) -> as_VIS H s msF1 = MS R1 F (Z_to_bv 64 0xf2538) fc None m1 (seg_rom asegs) -> rfull R1 ->
       PMXAT H LINV w s LB LBs m1 mo1 cj S_OPER TBL_EEF44 [] [] spal ->
       regs_tbl w R1 RT_OLJ -> PropExec.getr R1 3%bv = wa_gp w -> PropExec.getr R1 4%bv = wa_tp w ->
       PropExec.getr R1 27%bv = PropExec.getr R 27%bv ->
       ffkeep w m m1 ->
       as_SR H Q (mkCfg msF1 mo1)) ->
